package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;
public class AccountIdentityTest {
 @Test public void normalizesAddressSpelling(){assertEquals(AccountIdentity.owner(" HTTPS://NAS/ ","user"),AccountIdentity.owner("nas","user"));assertEquals("nas:5000|user",AccountIdentity.owner("http://NAS:5000/","user"));}
 @Test public void connectingDoesNotResetLibraries()throws Exception{String source=new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get("src/main/java/hu/synostream/android/MainActivity.java")),java.nio.charset.StandardCharsets.UTF_8);assertFalse(source.contains("s.libraries=LibraryConfig.migrate(new JSONArray())"));}
 @Test public void usernameCaseAndLegacyDataMigrateWithoutOverwritingNewData(){assertEquals(AccountIdentity.owner("nas","Admin"),AccountIdentity.owner("NAS/","admin"));TorrentRulesTest.Memory store=new TorrentRulesTest.Memory();store.put("libraries_owner","nas|Admin");store.put("edits:nas|Admin","{\"manual\":{\"movie:a\":{\"id\":1}}}");store.put("edits:nas|admin","{}");store.put("torrent_sites:nas|Admin","[{\"name\":\"Site\",\"url\":\"https://example.org\"}]");store.put("prepared:nas|Admin","[{\"list_id\":\"p1\"}]");store.put("torrent_choice:nas|Admin:p1","[0,1]");AccountIdentity.migrateKeys(store,"HTTPS://NAS/","admin");assertEquals(store.get("edits:nas|Admin",""),store.get("edits:nas|admin",""));assertEquals("[0,1]",store.get("torrent_choice:nas|admin:p1",""));assertTrue(store.get("torrent_sites:nas|admin","").contains("Site"));store.put("edits:nas|admin","{\"new\":1}");AccountIdentity.migrateKeys(store,"nas","ADMIN");assertEquals("{\"new\":1}",store.get("edits:nas|admin",""));}
 @Test public void anotherAccountCannotReceiveLegacyCorrections(){TorrentRulesTest.Memory store=new TorrentRulesTest.Memory();store.put("libraries_owner","nas|Admin");store.put("edits:nas|Admin","{\"private-fixture\":1}");AccountIdentity.migrateKeys(store,"nas","other-user");assertEquals("",store.get("edits:nas|other-user",""));}
}
